def normshape(shape):
 mn0=min(x for x,y in shape); mn1=min(y for x,y in shape)
 return frozenset((x-mn0,y-mn1) for x,y in shape)
def d4(sh):
 result=set()
 # rotate/reflection by treating coordinates x,y, square transforms
 for refl in [False,True]:
  for k in range(4):
   ss=[]
   for x,y in sh:
    if refl: y=-y
    for _ in range(k): x,y=y,-x
    ss.append((x,y))
   result.add(normshape(ss))
 return result
def matches_for(g,shape):
 ms=set()
 H,W=len(g),len(g[0])
 for sh in d4(shape):
  hh=max(x for x,y in sh)+1; ww=max(y for x,y in sh)+1
  for r in range(H-hh+1):
   for c in range(W-ww+1):
    if all(g[r+x][c+y]==0 for x,y in sh): ms.add((sh,r,c))
 return ms
